// Grading engine of e-meyar, copied from the teacher app (essay-grader,
// routes/grade.js at origin/main 0418ad2). Only the Express route, the
// Supabase parts and the require path of ./anthropic were removed.
//
// DO NOT EDIT THIS FILE IN THIS REPO. Grading changes are made in the teacher
// repo first, verified with its golden run, and then copied here.
// scripts/check-grader-sync.js fails if STATIC_SYSTEM, countWords or
// validateGradingResult differ from the teacher copy.
const anthropic = require("./anthropic");

const CRITERION_MAX = { A: 1.0, B: 2.0, C: 1.0, D: 1.0 };
const ALLOWED_ZERO_REASONS = ["under_70_words", "template_memorized", "whole_prompt_copied", "off_topic"];

// Static rubric prefix — identical on every grading call, so it is defined once
// at module scope and sent as a cached (ephemeral) system block. It must contain
// NO per-essay variables; the word count, prompt, and essay live in the dynamic
// block built per request by buildDynamicBlock().
// WITHHELD in this public snapshot: the calibrated DİM grading prompt (the
// core asset of our prior product e-meyar.az) is not published. It is read
// from the GRADING_PROMPT environment variable; the live demo has it set.
// Without it, grading stops with a clear error (see gradeEssay below).
const STATIC_SYSTEM = process.env.GRADING_PROMPT;

// Per-essay dynamic block — the only part that varies between calls. Wording is
// unchanged from the original prompt; these pieces were merely relocated out of
// STATIC_SYSTEM so the static rubric prefix can be cached.
function buildDynamicBlock(prompt_text, essay_text, word_count) {
  return `WORD COUNT
The essay has been counted deterministically by the system: ${word_count} words. Trust this exact number. Do not recount.

THE PROMPT (essay topic):
${prompt_text}

THE STUDENT ESSAY:
${essay_text}`;
}

// Validate the LLM response shape. Returns an error message string on failure,
// or null on success. Mutates `result` to enforce backend-authoritative fields.
function validateGradingResult(result, expectedWordCount) {
  if (!result || typeof result !== "object") {
    return "API cavabı obyekt deyil.";
  }

  // Backend is authoritative for word_count.
  result.word_count = expectedWordCount;

  // total_zero_reason
  const tzr = result.total_zero_reason;
  if (tzr !== null && !ALLOWED_ZERO_REASONS.includes(tzr)) {
    return "total_zero_reason yararsız dəyər daşıyır.";
  }

  // criteria
  if (!Array.isArray(result.criteria) || result.criteria.length !== 4) {
    return "criteria array dəqiq 4 element olmalıdır.";
  }
  const expectedIds = ["A", "B", "C", "D"];
  for (let i = 0; i < 4; i++) {
    const c = result.criteria[i];
    if (!c || typeof c !== "object") {
      return `criteria[${i}] obyekt deyil.`;
    }
    if (c.id !== expectedIds[i]) {
      return `criteria[${i}].id "${expectedIds[i]}" olmalıdır.`;
    }
    if (typeof c.score !== "number" || !isFinite(c.score)) {
      return `criteria[${i}].score ədəd deyil.`;
    }
    if (c.score < 0) {
      return `criteria[${i}].score mənfi ola bilməz.`;
    }
    const max = CRITERION_MAX[c.id];
    if (c.score > max + 0.0001) {
      return `criteria[${i}].score maksimumu (${max}) aşır.`;
    }
  }

  // raw_total = sum of criterion scores (tolerance 0.01)
  if (typeof result.raw_total !== "number" || !isFinite(result.raw_total)) {
    return "raw_total ədəd deyil.";
  }
  const sumScores = result.criteria.reduce((a, c) => a + c.score, 0);
  if (Math.abs(result.raw_total - sumScores) > 0.01) {
    return `raw_total (${result.raw_total}) meyar ballarının cəmindən (${sumScores.toFixed(2)}) fərqlidir.`;
  }

  // scaled_total = round(raw_total * 100 / 30, 1) (tolerance 0.05)
  if (typeof result.scaled_total !== "number" || !isFinite(result.scaled_total)) {
    return "scaled_total ədəd deyil.";
  }
  const expectedScaled = Math.round((result.raw_total * 100 / 30) * 10) / 10;
  if (Math.abs(result.scaled_total - expectedScaled) > 0.05) {
    return `scaled_total (${result.scaled_total}) gözlənilən dəyərdən (${expectedScaled}) fərqlidir.`;
  }

  // zero-override invariants
  if (tzr !== null) {
    for (let i = 0; i < 4; i++) {
      if (result.criteria[i].score !== 0) {
        return "total_zero_reason aktivdir, lakin bəzi meyar balları 0 deyil.";
      }
    }
    if (result.raw_total !== 0) {
      return "total_zero_reason aktivdir, lakin raw_total 0 deyil.";
    }
  }

  // errors array sanity
  if (!Array.isArray(result.errors)) {
    return "errors array deyil.";
  }
  if (tzr !== null && result.errors.length !== 0) {
    return "Zero-override aktivdir, errors boş olmalıdır.";
  }

  return null;
}

// Content-free summary of a grading result for server logs: scores and
// counts only. Never log essay text, error quotes or summaries.
function describeResult(r) {
  if (!r || typeof r !== "object") return typeof r;
  return {
    total_zero_reason: r.total_zero_reason,
    scores: Array.isArray(r.criteria)
      ? r.criteria.map((c) => (c && typeof c.score === "number" ? c.score : typeof c))
      : typeof r.criteria,
    raw_total: r.raw_total,
    scaled_total: r.scaled_total,
    error_count: Array.isArray(r.errors) ? r.errors.length : typeof r.errors,
  };
}

// Model and per-model request settings. Sonnet 4.6 pins temperature to 0.
// Sonnet 5+ rejects sampling parameters (400) and thinks by default, so there
// thinking is switched off to keep grading fast; its tokenizer also produces
// ~30% more tokens, hence the larger output budget.
const GRADING_MODEL = "claude-sonnet-5";

function modelSettings(model) {
  if (model.startsWith("claude-sonnet-4")) {
    return { max_tokens: 3000, temperature: 0 };
  }
  return { max_tokens: 8000, thinking: { type: "disabled" } };
}

// Same algorithm as the frontend (public/index.html), so the displayed count
// and the grader's count always agree.
function countWords(text) {
  return text.trim().split(/\s+/).filter((w) => w.length > 0).length;
}

// Unusable model output. Carries the message the route returns to the teacher
// and a content-free detail for the server log.
class GradingError extends Error {
  constructor(userMessage, logDetail) {
    super(userMessage);
    this.userMessage = userMessage;
    this.logDetail = logDetail;
  }
}

// Grades one essay: one API call, then parse + validate. Throws GradingError
// for unusable output; API errors propagate unchanged. Shared by POST
// /api/grade and scripts/golden-run.js, so a golden run always exercises the
// production prompt and settings. `overrides` exists for golden-run
// experiments (another model, thinking setting); the route never passes it.
async function gradeEssay({ prompt, essay, model = GRADING_MODEL, overrides = {} }) {
  if (!STATIC_SYSTEM) {
    throw new Error(
      "GRADING_PROMPT is not set: the calibrated grading prompt is withheld from this " +
      "public snapshot (see README, \"Withheld\"). Set GRADING_PROMPT to grade essays."
    );
  }
  const wordCount = countWords(essay);
  const started = Date.now();
  const stream = anthropic.messages.stream({
    model,
    ...modelSettings(model),
    system: [
      { type: "text", text: STATIC_SYSTEM, cache_control: { type: "ephemeral" } },
      { type: "text", text: buildDynamicBlock(prompt, essay, wordCount) },
    ],
    messages: [{ role: "user", content: "Grade the essay above and return the JSON object." }],
    ...overrides,
  });
  const message = await stream.finalMessage();
  const meta = { ms: Date.now() - started, usage: message.usage, stopReason: message.stop_reason };

  const textBlock = message.content.find((b) => b.type === "text");
  if (!textBlock) {
    throw new GradingError("API cavabında mətn tapılmadı.",
      `No text block in model response - stop_reason: ${message.stop_reason}`);
  }

  const jsonText = textBlock.text
    .trim()
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/, "")
    .replace(/\s*```$/, "");

  let result;
  try {
    result = JSON.parse(jsonText);
  } catch (parseErr) {
    // Position only: V8's parse-error message quotes a snippet of the text.
    const pos = /position (\d+)/.exec(parseErr.message);
    throw new GradingError("API cavabı düzgün JSON deyil.",
      `JSON parse error at position ${pos ? pos[1] : "?"} - model output length: ` +
      `${textBlock.text.length} chars, stop_reason: ${message.stop_reason}`);
  }

  const validationError = validateGradingResult(result, wordCount);
  if (validationError) {
    throw new GradingError("Qiymətləndirmə nəticəsi etibarsızdır: " + validationError,
      `Validation error: ${validationError} - result shape: ${JSON.stringify(describeResult(result))}`);
  }

  return { result, ...meta };
}

module.exports = {
  gradeEssay,
  GradingError,
  GRADING_MODEL,
  STATIC_SYSTEM,
  countWords,
  validateGradingResult,
};
